String antiShuffle(String s) {
  if (s.isEmpty) return '';

  String result = '';

  for (int i = 0; i < s.length / 2; i++) {
    int j = s.length - i - 1;

    if (i % 2 == 0 && !result.contains(s[i])) {
      result += s[i];
    } else if ((j % 2 != 0 || result.contains(s[j]))) {
      continue;
    } else if (!result.contains(s[j]) && (j % 2 == 0)) {
      result += s[j];
    }
  }

  return result + s.substring(result.length);
}

