      result += String.fromCharCode(newIndex + 97);

      if (i == s.length / 2) continue;
    } else if ((letterIndex >= 65 && letterIndex <= 90)) {
      // Uppercase letters
      int newIndex = (letterIndex - 65 + 4) % 26;
      result += String.fromCharCode(newIndex + 65);

      if (i == s.length / 2) continue;
    }
  }

  return result;
}

