bool checkDictCase(Map<dynamic, dynamic> dict) {
  if (dict.keys.isEmpty) {
    return false;
  } else {
    String state = "start";
    for (var key in dict.keys) {
      if (key is! String) {
        state = "mixed";
        break;
      }
      if (state == "start") {
        if (key == key.toUpperCase() && key != key.toLowerCase()) {
          state = "upper";
        } else if (key == key.toLowerCase() && key != key.toUpperCase()) {
          state = "lower";
        } else {
          break;
        }
      } else if ((state == "upper" && (key != key.toUpperCase() || key == key.toLowerCase())) ||
                 (state == "lower" && (key != key.toLowerCase() || key == key.toUpperCase()))) {
        state = "mixed";
        break;
      } else {
        break;
      }
    }
    return state == "upper" || state == "lower";
  }
}

