int maxFill(List<List<int>> grid, int capacity) {
  int total = 0;

  for (var i = 1; i < grid.length - 1; i++) {
    var row = grid[i];

    // Skip all-zero rows or non-empty rows already filled.
    if (row.every((cell) => cell == 0)) continue;

    var currentRowSum = row.where((cell) => cell == 1).length;
    var remainingCellsInRow = row.length - currentRowSum;

    var availableCapacityForThisRow = capacity * remainingCellsInRow;

    var canFullyFillRemainingCellsInThisRow = 
        currentRowSum + availableCapacityForThisRow >= row.length;

    if (!canFullyFillRemainingCellsInThisRow) break;

    while (remainingCellsInRow > 0 && capacity > 0) {
      total += 1;
      capacity -= 1;
      remainingCellsInRow -= 1;
    }
  }

  return total;
}

