  bool isPrime(int num) {
    if (num == 1 || num == 0) {
      return false;
    }
    if (num == 2) {
      return true;
    }
    for (int i = 2; i < num; i++) {
      if (num % i == 0) {
        return false;
      }
    }
    return true;
  }

  int l = interval1[0] > interval2[0] ? interval1[0] : interval2[0];
  int r = interval1[1] < interval2[1] ? interval1[1] : interval2[1];
  int length = r - l;
  if (length > 0 && isPrime(length)) {
