  if (lst.isEmpty || lst.length == 1) return [null, null];

  int min = lst[0], max = lst[0];
  for (int num in lst) {
    if (num < min) min = num;
    if (num > max) max = num;
  }

  List<dynamic> result = [];

  bool foundMin = false;
  for (int i = 1; i < lst.length - 1 && !foundMin; i++) {
    if (lst[i] != min) {
      result.add(min);
      break;
    }
  }

  // If no second smallest was found yet and list has at least two elements:
  if (!foundMin && lst.length >= 2) {
    foundMin = true; 
    result.add(lst[1]); // fallback only when previous loop didn't trigger.
  } else if (!foundMin) {
    result.add(null); 
  }


  return result;
}

