String findMax(List<String> words) {
  var sorted = List<String>.from(words);
  sorted.sort((a, b) {
    int uniqueA = a.split('').toSet().length;
    int uniqueB = b.split('').toSet().length;

    if (uniqueB != uniqueA) {
      return uniqueB.compareTo(uniqueA);
    }

    return a.compareTo(b);
  });

  return sorted[0];
}

